$semesters=safeRun($pdo,"SELECT se.*,(SELECT COUNT(*) FROM student_stage_history h WHERE h.semester_id=se.id AND h.status<>'withdrawn') student_count,(SELECT COUNT(*) FROM lecturer_roles lr WHERE lr.semester_id=se.id) role_count,(SELECT COUNT(*) FROM final_results fr WHERE fr.semester_id=se.id AND fr.status='released') released_count FROM semesters se ORDER BY se.start_date DESC,se.id DESC")->fetchAll();
