<?php elseif($subTab==='lecturers'):$rows=safeRun($pdo,"SELECT l.id,u.full_name,u.email,GROUP_CONCAT(CONCAT(lr.role_type,'|',lr.programme_type) ORDER BY FIELD(lr.role_type,'coordinator','supervisor','report_panel','presentation_panel') SEPARATOR ';;') roles FROM lecturers l JOIN users u ON u.id=l.user_id LEFT JOIN lecturer_roles lr ON lr.lecturer_id=l.id AND lr.semester_id=? GROUP BY l.id,u.id ORDER BY u.full_name",[$semId])->fetchAll(); ?><table class="table-fy"><thead><tr><th>Lecturer</th><th>Department</th><th>Semester Roles</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e(drName($r['full_name'])) ?></strong><div class="small text-muted"><?= e($r['email']) ?></div></td><td>Department of Computing</td><td><?php $pairs=array_filter(explode(';;',(string)$r['roles']));if(!$pairs): ?><span class="small text-muted">No role assigned</span><?php else:foreach($pairs as $pair):[$role,$programme]=array_pad(explode('|',$pair,2),2,''); ?><div class="small"><strong><?= e(roleLabel($role)) ?></strong> — <?= e(programmeTypeLabel($programme)) ?></div><?php endforeach;endif; ?></td></tr><?php endforeach; ?></tbody></table>
