<?php else:
$search='';$params=[$semId];if($q!==''){$search=' AND (u.full_name LIKE ? OR s.matric_number LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}$project=safeRun($pdo,"SELECT sub.id,sub.file_name,sub.uploaded_at,u.full_name,s.matric_number,sc.name item_name FROM submissions sub JOIN students s ON s.id=sub.student_id JOIN users u ON u.id=s.user_id JOIN submission_categories sc ON sc.id=sub.category_id WHERE sub.semester_id=? $search AND sub.id=(SELECT MAX(x.id) FROM submissions x WHERE x.student_id=sub.student_id AND x.category_id=sub.category_id AND x.semester_id=sub.semester_id)",$params)->fetchAll();$params2=[$semId];if($q!==''){$params2[]='%'.$q.'%';$params2[]='%'.$q.'%';}$progress=safeRun($pdo,"SELECT ps.id,ps.file_name,ps.submitted_at,u.full_name,s.matric_number,pf.title item_name FROM progress_submissions ps JOIN progress_forms pf ON pf.id=ps.progress_form_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE pf.semester_id=? $search",$params2)->fetchAll(); ?>
<form method="get" class="d-flex gap-2 mb-3"><input type="hidden" name="view" value="semesters"><input type="hidden" name="sem_id" value="<?= $semId ?>"><input type="hidden" name="sub" value="uploads"><input name="q" value="<?= e($q) ?>" class="form-control-fy" placeholder="Search name or matric number"><button class="btn-fy-orange">Search</button></form><table class="table-fy"><thead><tr><th>Student</th><th>Type</th><th>Category / Form</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($project as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['matric_number']) ?></div></td><td>Project Submission</td><td><?= e($r['item_name']) ?><div class="small text-muted"><?= e($r['file_name']) ?></div></td><td><?= timeAgo($r['uploaded_at']) ?></td><td><a class="btn-fy-outline btn-sm" target="_blank" href="<?= e(secureFileUrl((int)$r['id'],'submission')) ?>">View</a></td></tr><?php endforeach; ?><?php foreach($progress as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['matric_number']) ?></div></td><td>Progress Form</td><td><?= e($r['item_name']) ?><div class="small text-muted"><?= e($r['file_name']) ?></div></td><td><?= timeAgo($r['submitted_at']) ?></td><td><a class="btn-fy-outline btn-sm" target="_blank" href="<?= e(secureFileUrl((int)$r['id'],'progress_submission')) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$project&&!$progress): ?><tr><td colspan="5" class="text-center text-muted py-4">No matching uploads.</td></tr><?php endif; ?></tbody></table>
<?php endif; ?></div></div><?php endif; ?>
